bg=2
out=[[bg]*13 for _ in range(13)]
panels={(1,1): (9, [[1,0,1],[1,1,1],[0,1,0]]), (1,7):(6,[[0,1,1],[0,1,1],[1,0,0]]), (7,1):(3,[[1,0,1],[0,1,1],[0,1,0]]), (7,7):(4,[[1,1,1],[0,1,0],[0,1,0]])}
for (r,c),(color,mask) in panels.items():
    for i in range(5):
        for j in range(5): out[r+i][c+j]=color
    for i in range(3):
        for j in range(3):
            if mask[i][j]: out[r+1+i][c+1+j]=bg
print('\n'.join(str(row) for row in out))
